#ifndef LINKED_LIST_H
#define LINKED_LIST_H

#include <vector>
#include "node.h"

class LinkedList {
public:
    LinkedList() : head(nullptr) {}
    ~LinkedList() {
        while (head != nullptr) {
            Node* next = head->next;
            delete head;
            head = next;
        }
    }
    LinkedList(const LinkedList&) = delete;
    LinkedList& operator=(const LinkedList&) = delete;

    void pushBack(int value) {
        Node** tail = &head;
        while (*tail != nullptr) tail = &(*tail)->next;
        *tail = new Node{value, nullptr};
    }
    Node* getHead() const { return head; }

    void insertAfterMax(int value);                    // ex08
    int removeNotIn(const int arr[], int size);        // ex09
    std::vector<int> newMinimums() const;              // ex10

private:
    Node* head;
};

#endif
